```cpp
#include <iostream>
#include <limits>

using namespace std;

// Recursive Fibonacci function with error handling
pair<int, int> fibonacci(int prev1, int prev2, int n) {
    if (n <= 0) {
        return make_pair(prev1, prev2); // Base case: Return initial values for n <= 0
    } else if (n == 1) {
        return make_pair(prev2, prev1 + prev2); // First element after initial pair
    } else {
        auto nextPair = fibonacci(prev2, prev1 + prev2, n - 1);
        return nextPair; // Recursively calculate and return the next pair
    }
}

int main() {
    int num1, num2, count;
    cout << "Enter the first two Fibonacci numbers: ";
    while (!(cin >> num1 >> num2) || num1 < 0 || num2 < 0) {  // Input validation loop
        cout << "Invalid input. Please enter two non-negative integers: ";
        cin.clear();  // Clear error state
        cin.ignore(numeric_limits<streamsize>::max(), '\n'); // Discard invalid input
    }

    cout << "Enter the desired number of sequence elements: ";
    while (!(cin >> count) || count <= 0) {
        cout << "Invalid input. Please enter a positive integer: ";
        cin.clear();
        cin.ignore(numeric_limits<streamsize>::max(), '\n');
    }

    auto sequenceStart = fibonacci(num1, num2, 2); // Initialize with given values
    cout << sequenceStart.first << ", " << sequenceStart.second; // Output initial pair

    for (int i = 3; i <= count; ++i) {
        auto nextPair = fibonacci(sequenceStart.second, sequenceStart.first + sequenceStart.second, i);
        cout << ", " << nextPair.second; 
        sequenceStart = nextPair; // Update for next iteration
    }

    cout << endl;
    return 0;
}
```

