    var vid2 = Import Footage(file2);

    // 3. Vertical Stacking
    var stackComp = comp.duplicate();  // Work on a copy of the composition
    stackComp.name = "VerticalStack"; 

    var height = Math.max(vid1.duration * vid1.frameRate, vid2.duration * vid2.frameRate) * comp.height /  comp.duration * frameRate; // Ensure combined height matches
    var topLayer = new Solid(width: comp.width, height: height / 2);
    var bottomLayer = new Solid(width: comp.width, height: height / 2);
    stackComp.layers.add(topLayer);
    stackComp.layers.add(bottomLayer);

    topLayer.replace Footage(vid1);
    bottomLayer.replace Footage(vid2);
